def better_deal(p1, d1, p2, d2):
    if p1 * (100 - d1) <= p2 * (100 - d2):
        return 1
    return 2

def is_num_pal(n):
    if n < 0:
        return False
    original = n
    rev = 0
    while n > 0:
        rev = rev * 10 + n % 10
        n //= 10
    return rev == original

def compound_int(p, r, t, n=1):
    amount = p * (1 + r / (100 * n)) ** (n * t)
    return round(amount, 2)

def append_entry(e, led=None):
    if led is None:
        led = []
    led.append(e)
    return led

def calc_tax(income):
    tax = 0.0
    if income > 500000:
        tax += (income - 500000) * 0.20
        income = 500000
    if income > 250000:
        tax += (income - 250000) * 0.10
    return round(tax, 2)

def calc_emi(p, r, n):
    if r == 0:
        return round(p / n, 2)
    m = r / 12 / 100
    f = (1 + m) ** n
    return round(p * m * f / (f - 1), 2)

def gcd_lcm(a, b):
    x, y = a, b
    while y:
        x, y = y, x % y
    return (x, a * b // x)

import math

def solve_quad(a, b, c):
    d = b * b - 4 * a * c
    if d < 0:
        return ()
    if d == 0:
        return (round(-b / (2 * a), 4) + 0.0,)
    s = math.sqrt(d)
    r1 = round((-b - s) / (2 * a), 4) + 0.0
    r2 = round((-b + s) / (2 * a), 4) + 0.0
    return tuple(sorted((r1, r2)))

def safe_int(val, default=0):
    try:
        return int(val)
    except ValueError:
        return default

def convert_temp(v, fr, to):
    if fr not in ("C", "F", "K") or to not in ("C", "F", "K"):
        raise ValueError("invalid unit")
    v = float(v)
    if fr == "C":
        c = v
    elif fr == "F":
        c = (v - 32) * 5 / 9
    else:
        c = v - 273.15
    if to == "C":
        out = c
    elif to == "F":
        out = c * 9 / 5 + 32
    else:
        out = c + 273.15
    return round(out, 2)

def fact(k):
    result = 1
    for i in range(2, k + 1):
        result *= i
    return result

def perm_count(n, r):
    if n < 0 or r < 0:
        raise ValueError("n and r must be non-negative")
    if r > n:
        return 0
    return fact(n) // fact(n - r)

def sqrt_bisect(n, eps=1e-6):
    if n < 0:
        raise ValueError("n must be non-negative")
    low = 0.0
    high = max(1.0, n)
    while high - low > eps:
        mid = (low + high) / 2
        if mid * mid < n:
            low = mid
        else:
            high = mid
    return round((low + high) / 2, 6)
